package binding

import (
	"bytes"
	"mime/multipart"
	"net/http"
	"testing"
)

func TestTmpNonMandatoryFile(t *testing.T) {
	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	mw.WriteField("name", "test-name")
	mw.WriteField("email", "test@email.com")
	// part with empty filename (browser sends this when no file selected)
	fw, _ := mw.CreateFormFile("file", "")
	fw.Write(nil)
	mw.Close()

	req, _ := http.NewRequest("POST", "/", &body)
	req.Header.Set("Content-Type", MIMEMultipartPOSTForm+"; boundary="+mw.Boundary())

	var s struct {
		Name  string                `form:"name" binding:"required"`
		Email string                `form:"email" binding:"required"`
		File  *multipart.FileHeader `form:"file"`
	}
	if err := FormMultipart.Bind(req, &s); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if s.Name != "test-name" || s.Email != "test@email.com" {
		t.Fatalf("bad fields: %+v", s)
	}
}
